#!/usr/bin/env bash

if [ $# -ne 4 ]; then
    echo "Usage: $0 <tok-exp> <inference-tag> <inference-model> <test-sets>" 1>&2
    echo ""
    echo "Show the system environments and the evaluation results in Markdown format."
    exit 1
fi

[ -f ./path.sh ] && . ./path.sh
set -euo pipefail

tok_exp=$1
inference_tag=$2
inference_model=$3
test_sets=$4
train_config=$(sed -n 's/^config: //p' "${tok_exp}/config.yaml")


cat << EOF
<!-- Generated by $0 -->
# RESULTS
## Environments
- date: \`$(LC_ALL=C date)\`
EOF

python3 << EOF
import sys, espnet2, torch
pyversion = sys.version.replace('\n', ' ')

print(f"""- python version: \`{pyversion}\`
- espnet2 version: \`espnet2 {espnet2.__version__}\`
- pytorch version: \`pytorch {torch.__version__}\`""")
EOF

cat << EOF
- Git hash: \`$(git rev-parse HEAD)\`
  - Commit date: \`$(git log -1 --format='%cd')\`

## Experiment configuration
- training config: \`${train_config}\`
- resolved config: [config.yaml](config.yaml)
- inference model: \`${inference_model}\`
- inference tag: \`${inference_tag}\`

## ASR branch
EOF

for score_type in wer cer; do
    cat << EOF
### ${score_type^^}

|dataset|Snt|Wrd|Corr|Sub|Del|Ins|Err|S.Err|
|---|---|---|---|---|---|---|---|---|
EOF
    for dset in ${test_sets}; do
        result=${tok_exp}/${inference_tag}/${dset}/score/result_${score_type}.txt
        line=$(grep -e Sum/Avg "${result}" | tail -n 1)
        echo "${line}" \
            | sed -e "s#^|[[:space:]]*Sum/Avg[[:space:]]*#|${dset}#" \
            | tr ' ' '|' | tr -s '|'
    done
    echo
done

cat << EOF
## Reconstruction branch

|dataset|MCD|F0 RMSE|F0 correlation|Speaker similarity|UTMOS|Whisper WER|Whisper CER|
|---|---|---|---|---|---|---|---|
EOF

f0_exclusion_rows=""
for dset in ${test_sets}; do
    result=${tok_exp}/${inference_tag}/${dset}/score/versa/avg_result.txt
    utt_result=${tok_exp}/${inference_tag}/${dset}/score/versa/utt_result.txt
    read -r f0rmse f0rmse_excluded f0corr f0corr_excluded < <(
        python3 - "${utt_result}" <<'PY'
import re
import sys

import numpy as np


lines = open(sys.argv[1], encoding="utf-8").readlines()


def summarize(metric):
    pattern = re.compile(rf"'{metric}': ([^,}}]+)")
    values = np.array([float(pattern.search(line).group(1)) for line in lines])
    excluded = int(np.isnan(values).sum())
    mean = "nan" if excluded == len(values) else f"{np.nanmean(values):.2f}"
    return mean, excluded


print(*summarize("f0rmse"), *summarize("f0corr"))
PY
    )
    line="|${dset}"
    for metric in mcd f0rmse f0corr spk_similarity utmos whisper_wer whisper_cer; do
        if [[ "${metric}" == f0rmse ]]; then
            value=${f0rmse}
        elif [[ "${metric}" == f0corr ]]; then
            value=${f0corr}
        else
            value=$(awk -v metric="${metric}" '
                $1 == metric ":" || $1 == metric {
                    scale = metric ~ /^whisper_/ ? 100 : 1
                    printf "%.2f", $2 * scale
                }
            ' "${result}")
        fi
        line+="|${value}"
    done
    echo "${line}|"
    f0_exclusion_rows+="|${dset}|${f0rmse_excluded}|${f0corr_excluded}|"$'\n'
done

cat << EOF

F0 metrics use the mean over non-NaN utterances. Excluded utterance counts:

|dataset|F0 RMSE|F0 correlation|
|---|---|---|
${f0_exclusion_rows%$'\n'}
EOF
